	private static void assertEncodedSizeRollover(Fixture fixture, Snapshot before, Snapshot after, long next)
			throws IOException {
		assertEquals(before.cold().size() + 1, after.cold().size());
		assertEquals(List.of(next), pack(after.hot()).transactions());
		List<Frame> attempted = new ArrayList<>(pack(before.hot()).frames());
		attempted.add(pack(after.hot()).frames().getFirst());
		byte[] combined = packedRow(COLD, attempted).value();
		assertTrue(combined.length <= fixture.packLimit,
				"The attempted decoded pack must remain below the native bound");
		assertTrue(combined.length > LmdbBackupCatalogTestSupport.packCapacity(before.hot().value().length));
		int encoded = LZ4Factory.fastestInstance().fastCompressor().compress(combined).length
				+ LmdbBackupCatalogTestSupport.COMPRESSED_HEADER_BYTES;
		assertTrue(encoded > before.hot().value().length,
				"Actual framed source bytes must overflow the encoded reservation before the decoded bound");
		long terminal = pack(before.hot()).frames().getLast().transaction();
		Row evacuated = after.cold()
				.stream()
				.filter(row -> row.terminalTransaction() == terminal)
				.findFirst()
				.orElseThrow();
		assertEquals(packedDatabase(terminal), evacuated.database());
		assertArrayEquals(packValue(before.hot()), evacuated.value(),
				"Encoded-size fallback must retain every original Pack v1 byte in cold storage");
	}

	private static List<Record> catalogEntropyRecords() {
		var values = SimpleValueFactory.getInstance();
		Random random = new Random(0x43504b32L);
		List<Record> records = new ArrayList<>();
		for (int index = 0; index < 5; index++) {
			Statement statement = values.createStatement(values.createIRI("urn:s:" + entropy(random, 16)),
					values.createIRI("urn:p:" + entropy(random, 16)),
					values.createIRI("urn:o:" + entropy(random, 116)));
			records.add(new Record(true, true, statement));
		}
		return records;
	}

	private static String entropy(Random random, int length) {
		String alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
		StringBuilder value = new StringBuilder(length);
		for (int index = 0; index < length; index++) {
			value.append(alphabet.charAt(random.nextInt(alphabet.length())));
		}
		return value.toString();
	}

